 "content": "from collections import Counter, deque


def transform(grid):
    """Replace isolated singleton-color noise pixels with their local field color."""
    h, w = len(grid), len(grid[0])
    seen = [[False] * w for _ in range(h)]
    components = Counter()
    component_sizes = {}

    for r in range(h):
        for c in range(w):
            if seen[r][c]:
                continue
            color = grid[r][c]
            q = deque([(r, c)])
            seen[r][c] = True
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and not seen[ny][nx] and grid[ny][nx] == color:
                        seen[ny][nx] = True
                        q.append((ny, nx))
            components[color] += 1
            component_sizes[(color, len(cells))] = component_sizes.get((color, len(cells)), 0) + 1

    # A color used only for isolated one-cell marks is noise; colors forming
    # connected shapes/regions are preserved as part of the underlying image.
    counts = Counter(v for row in grid for v in row)
    noise = set()
    for color in counts:
        sizes = []
        visited = [[False] * w for _ in range(h)]
        for r in range(h):
            for c in range(w):
                if grid[r][c] != color or visited[r][c]:
                    continue
                q = deque([(r, c)])
                visited[r][c] = True
                size = 0
                while q:
                    y, x = q.popleft()
                    size += 1
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < h and 0 <= nx < w and not visited[ny][nx] and grid[ny][nx] == color:
                            visited[ny][nx] = True
                            q.append((ny, nx))
                sizes.append(size)
        if sizes and all(size == 1 for size in sizes):
            noise.add(color)

    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] not in noise:
                continue
            around = [grid[y][x]
                      for y in range(max(0, r - 1), min(h, r + 2))
                      for x in range(max(0, c - 1), min(w, c + 2))
                      if (y, x) != (r, c) and grid[y][x] not in noise]
            if not around:
                continue
            freq = Counter(around)
            best = max(freq.values())
            candidates = [color for color, n in freq.items() if n == best]
            # Resolve ties with the four directly adjacent cells, then prefer
            # the color of the closest valid neighbor.
            orth = [grid[y][x] for y, x in ((r-1,c),(r+1,c),(r,c-1),(r,c+1))
                    if 0 <= y < h and 0 <= x < w and grid[y][x] not in noise]
            orth_freq = Counter(orth)
            best_orth = max((orth_freq[color] for color in candidates), default=0)
            candidates = [color for color in candidates if orth_freq[color] == best_orth]
            if len(candidates) > 1:
                closest = None
                for distance in range(1, max(h, w) + 1):
                    found = []
                    for y in range(max(0, r-distance), min(h, r+distance+1)):
                        for x in range(max(0, c-distance), min(w, c+distance+1)):
                            if abs(y-r) + abs(x-c) != distance or grid[y][x] in noise:
                                continue
                            if grid[y][x] in candidates:
                                found.append(grid[y][x])
                    if found:
                        closest = found[0]
                        break
                if closest in candidates:
                    replacement = closest
                else:
                    replacement = candidates[0]
            else:
                replacement = candidates[0]
            out[r][c] = replacement
    return out
