 "content": "from collections import Counter, deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = [[False] * w for _ in range(h)]
    components = Counter()
    for r in range(h):
        for c in range(w):
            if seen[r][c]:
                continue
            color = grid[r][c]
            q = deque([(r, c)])
            seen[r][c] = True
            size = 0
            while q:
                y, x = q.popleft()
                size += 1
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and not seen[ny][nx] and grid[ny][nx] == color:
                        seen[ny][nx] = True
                        q.append((ny, nx))
            components[color] += 1
            if size != 1:
                components[(color, "non_singleton")] += 1

    colors = set(v for row in grid for v in row)
    noise = {color for color in colors if components[color] == components.get((color, "non_singleton"), 0)}
    # A color is noise only when every connected component consists of one cell.
    noise = {color for color in colors if components.get((color, "non_singleton"), 0) == 0}

    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] not in noise:
                continue
            around = [grid[y][x]
                      for y in range(max(0, r - 1), min(h, r + 2))
                      for x in range(max(0, c - 1), min(w, c + 2))
                      if (y, x) != (r, c) and grid[y][x] not in noise]
            if not around:
                continue
            counts = Counter(around)
            best = max(counts.values())
            candidates = {color for color, n in counts.items() if n == best}
            if len(candidates) > 1:
                # Prefer orthogonal evidence when the 8-neighborhood ties.
                orth_order = ((r, c - 1), (r + 1, c), (r - 1, c), (r, c + 1))
                orth = [grid[y][x] for y, x in orth_order
                        if 0 <= y < h and 0 <= x < w and grid[y][x] in candidates]
                if orth:
                    orth_counts = Counter(orth)
                    best_orth = max(orth_counts.values())
                    candidates = {color for color, n in orth_counts.items() if n == best_orth}
            if len(candidates) > 1:
                for y, x in ((r, c - 1), (r + 1, c), (r - 1, c), (r, c + 1),
                             (r + 1, c - 1), (r - 1, c - 1), (r + 1, c + 1), (r - 1, c + 1)):
                    if 0 <= y < h and 0 <= x < w and grid[y][x] in candidates:
                        replacement = grid[y][x]
                        break
                else:
                    replacement = min(candidates)
            else:
                replacement = next(iter(candidates))
            out[r][c] = replacement
    return out
