 "content": "from collections import Counter, deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    totals = Counter(value for row in grid for value in row)
    background = totals.most_common(1)[0][0]

    # Noise colors occur only as isolated one-cell components. Every real
    # object/color has at least one multi-cell component, including the 2x2
    # and 3x3 objects shown in the demos.
    seen = [[False] * w for _ in range(h)]
    has_non_singleton = set()
    for r in range(h):
        for c in range(w):
            if seen[r][c]:
                continue
            color = grid[r][c]
            q = deque([(r, c)])
            seen[r][c] = True
            size = 0
            while q:
                y, x = q.popleft()
                size += 1
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and not seen[ny][nx]
                            and grid[ny][nx] == color):
                        seen[ny][nx] = True
                        q.append((ny, nx))
            if size > 1:
                has_non_singleton.add(color)
    noise = set(totals) - has_non_singleton

    # Fill each noisy cell using the most frequent surrounding non-noise
    # color. On ties, keep the original value if it is among the choices;
    # otherwise use a deterministic neighbor order.
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] not in noise:
                continue
            neighbors = [grid[y][x]
                         for y in range(max(0, r - 1), min(h, r + 2))
                         for x in range(max(0, c - 1), min(w, c + 2))
                         if (y, x) != (r, c) and grid[y][x] not in noise]
            if not neighbors:
                out[r][c] = background
                continue
            freq = Counter(neighbors)
            max_count = max(freq.values())
            candidates = {color for color, n in freq.items() if n == max_count}
            if grid[r][c] in candidates:
                out[r][c] = grid[r][c]
                continue
            # If opposite cells match, the mark interrupts a straight object.
            if r > 0 and r + 1 < h and grid[r - 1][c] == grid[r + 1][c] and grid[r - 1][c] in candidates:
                out[r][c] = grid[r - 1][c]
            elif c > 0 and c + 1 < w and grid[r][c - 1] == grid[r][c + 1] and grid[r][c - 1] in candidates:
                out[r][c] = grid[r][c - 1]
            elif len(candidates) == 1:
                out[r][c] = next(iter(candidates))
            else:
                for y, x in ((r, c - 1), (r + 1, c), (r - 1, c), (r, c + 1),
                             (r - 1, c - 1), (r + 1, c - 1), (r - 1, c + 1), (r + 1, c + 1)):
                    if 0 <= y < h and 0 <= x < w and grid[y][x] in candidates:
                        out[r][c] = grid[y][x]
                        break
                else:
                    out[r][c] = background
    return out
