 "content": "from collections import Counter, deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = [[False] * w for _ in range(h)]
    components = []
    for r in range(h):
        for c in range(w):
            if seen[r][c]:
                continue
            color = grid[r][c]
            q = deque([(r, c)])
            seen[r][c] = True
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and not seen[ny][nx]
                            and grid[ny][nx] == color):
                        seen[ny][nx] = True
                        q.append((ny, nx))
            components.append((color, cells))

    # Determine the canvas as the color with largest connected component.
    component_sizes = Counter()
    for color, cells in components:
        component_sizes[color] = max(component_sizes[color], len(cells))
    background = max(component_sizes, key=component_sizes.get)
    noise = set()
    for color in {v for row in grid for v in row}:
        same = [cells for col, cells in components if col == color]
        if same and all(len(cells) == 1 for cells in same):
            noise.add(color)
    noise.discard(background)

    out = [row[:] for row in grid]
    for color, cells in components:
        if color not in noise:
            continue
        for r, c in cells:
            # Select the surrounding non-noise color with greatest 8-neighbor
            # support; ties are resolved by orthogonal direction ordering.
            around = [grid[y][x]
                      for y in range(max(0, r - 1), min(h, r + 2))
                      for x in range(max(0, c - 1), min(w, c + 2))
                      if (y, x) != (r, c) and grid[y][x] not in noise]
            if not around:
                out[r][c] = background
                continue
            freq = Counter(around)
            best = max(freq.values())
            candidates = {value for value, n in freq.items() if n == best}
            # Preserve an object color when it has maximal local support.
            if grid[r][c] in candidates:
                out[r][c] = grid[r][c]
                continue
            order = ((r, c - 1), (r + 1, c), (r - 1, c), (r, c + 1),
                     (r - 1, c - 1), (r + 1, c - 1), (r - 1, c + 1), (r + 1, c + 1))
            out[r][c] = next((grid[y][x] for y, x in order
                              if 0 <= y < h and 0 <= x < w and grid[y][x] in candidates),
                             background)
    return out
