def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = [[False] * w for _ in range(h)]
    components = []
    for r in range(h):
        for c in range(w):
            if seen[r][c]:
                continue
            color = grid[r][c]
            queue = deque([(r, c)])
            seen[r][c] = True
            cells = []
            while queue:
                y, x = queue.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and not seen[ny][nx]
                            and grid[ny][nx] == color):
                        seen[ny][nx] = True
                        queue.append((ny, nx))
            components.append((color, cells))

    # The background is the most frequent cell color, and all isolated
    # singleton colors are noise. In the second demo, color 0 is a 3x3 body,
    # so it is not removed.
    totals = Counter(v for row in grid for v in row)
    background = totals.most_common(1)[0][0]
    has_multi = {color for color, cells in components if len(cells) > 1}
    noise = set(totals) - has_multi

    output = [row[:] for row in grid]
    for color, cells in components:
        if color not in noise:
            continue
        for r, c in cells:
            # Replace each speck with the most common neighboring non-noise
            # color; ties favor the original cell color, then stable scan order.
            around = [grid[y][x]
                      for y in range(max(0, r - 1), min(h, r + 2))
                      for x in range(max(0, c - 1), min(w, c + 2))
                      if (y, x) != (r, c) and grid[y][x] not in noise]
            if not around:
                output[r][c] = background
                continue
            frequencies = Counter(around)
            best = max(frequencies.values())
            if color in frequencies and frequencies[color] == best:
                output[r][c] = color
                continue
            choices = {v for v, n in frequencies.items() if n == best}
            # Continue the shape line through a tied singleton, if possible.
            if r > 0 and r + 1 < h and grid[r - 1][c] == grid[r + 1][c] and grid[r - 1][c] in choices:
                output[r][c] = grid[r - 1][c]
            elif c > 0 and c + 1 < w and grid[r][c - 1] == grid[r][c + 1] and grid[r][c - 1] in choices:
