                         (r - 1, c - 1), (r + 1, c - 1), (r - 1, c + 1), (r + 1, c + 1))
                output[r][c] = next((grid[y][x] for y, x in order
                                     if 0 <= y < h and 0 <= x < w and grid[y][x] in choices), background)
    return output
