 "content": "from collections import Counter, deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = [[False] * w for _ in range(h)]
    components = []
    for r in range(h):
        for c in range(w):
            if seen[r][c]:
                continue
            color = grid[r][c]
            queue = deque([(r, c)])
            seen[r][c] = True
            cells = []
            while queue:
                y, x = queue.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and not seen[ny][nx] and grid[ny][nx] == color:
                        seen[ny][nx] = True
                        queue.append((ny, nx))
            components.append((color, cells))

    totals = Counter(v for row in grid for v in row)
    background = totals.most_common(1)[0][0]
    multi = {color for color, cells in components if len(cells) > 1}
    noise = set(totals) - multi

    out = [row[:] for row in grid]
    for color, cells in components:
        if color not in noise:
            continue
        for r, c in cells:
            # Infer replacement based on direct orthogonal neighbors. That
            # avoids diagonal background bias near edges of block objects.
            order = ((r, c - 1), (r + 1, c), (r - 1, c), (r, c + 1))
            neighbors = [grid[y][x] for y, x in order
                         if 0 <= y < h and 0 <= x < w and grid[y][x] not in noise]
            if not neighbors:
                out[r][c] = background
                continue
            frequency = Counter(neighbors)
            highest = max(frequency.values())
            candidates = {v for v, n in frequency.items() if n == highest}
            # If surrounding color evidence ties, continue the underlying
            # shape horizontally/vertically before defaulting to background.
            if r > 0 and r + 1 < h and grid[r - 1][c] == grid[r + 1][c] and grid[r - 1][c] in candidates:
                out[r][c] = grid[r - 1][c]
            elif c > 0 and c + 1 < w and grid[r][c - 1] == grid[r][c + 1] and grid[r][c - 1] in candidates:
                out[r][c] = grid[r][c - 1]
            elif len(candidates) == 1:
                out[r][c] = next(iter(candidates))
            else:
                out[r][c] = background if background in candidates else min(candidates)
    return out
