 "content": "from collections import Counter, deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = [[False] * w for _ in range(h)]
    components = []
    for r in range(h):
        for c in range(w):
            if seen[r][c]:
                continue
            color = grid[r][c]
            q = deque([(r, c)])
            seen[r][c] = True
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and not seen[ny][nx]
                            and grid[ny][nx] == color):
                        seen[ny][nx] = True
                        q.append((ny, nx))
            components.append((color, cells))

    # Singleton-only colors are injected marks; preserve connected objects.
    multi = {color for color, cells in components if len(cells) > 1}
    noise = {color for color, _ in components} - multi
    # Grid background is the most frequent color, and isn't erased even if
    # its edge components happen to be singletons (normally not applicable).
    totals = Counter(v for row in grid for v in row)
    background = totals.most_common(1)[0][0]
    noise.discard(background)

    out = [row[:] for row in grid]
    for color, cells in components:
        if color not in noise:
            continue
        for r, c in cells:
            neighbors = [grid[y][x]
                         for y in range(max(0, r - 1), min(h, r + 2))
                         for x in range(max(0, c - 1), min(w, c + 2))
                         if (y, x) != (r, c) and grid[y][x] not in noise]
            if not neighbors:
                out[r][c] = background
                continue
            freq = Counter(neighbors)
            best = max(freq.values())
            tied = {v for v, n in freq.items() if n == best}
            # If a singleton divides a two-tone object, select the color that
            # forms a multi-cell horizontal/vertical run through that location.
            for direction in ((0, 1), (1, 0)):
                dr, dc = direction
                same = []
                for sign in (-1, 1):
                    y, x = r + sign * dr, c + sign * dc
                    same.append(grid[y][x] if 0 <= y < h and 0 <= x < w else None)
                if same[0] == same[1] and same[0] in tied:
                    out[r][c] = same[0]
                    break
            else:
                # Majority in a wider neighborhood usually reflects the
                # underlying rectangular region, rather than diagonal noise.
                out[r][c] = next((v for v, _ in freq.most_common() if v in tied), background)
    return out
