def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = [[False] * w for _ in range(h)]
    comps = []
    for r in range(h):
        for c in range(w):
            if seen[r][c]:
                continue
            color = grid[r][c]
            q = deque([(r, c)])
            seen[r][c] = True
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and not seen[ny][nx] and grid[ny][nx] == color:
                        seen[ny][nx] = True
                        q.append((ny, nx))
            comps.append((color, cells))

    background = max(comps, key=lambda item: len(item[1]))[0]
    colors = {v for row in grid for v in row}
    multi = {color for color, cells in comps if len(cells) > 1}
    noise = colors - multi
    noise.discard(background)

    out = [row[:] for row in grid]
    for color, cells in comps:
        if color not in noise:
            continue
        for r, c in cells:
            # Fill a noise pixel with the color that has the strongest local
            # support. Shape pixels win when tied with the global background.
            counts = Counter()
            for y in range(max(0, r - 2), min(h, r + 3)):
                for x in range(max(0, c - 2), min(w, c + 3)):
                    if (y, x) != (r, c) and grid[y][x] not in noise:
                        distance = abs(y-r) + abs(x-c)
                        counts[grid[y][x]] += 1.0 / distance
            if not counts:
                out[r][c] = background
                continue
            max_score = max(counts.values())
            candidates = {v for v, score in counts.items() if score == max_score}
            if background in candidates and len(candidates) > 1:
                candidates.remove(background)
            out[r][c] = min(candidates)
    return out
