def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = [[False] * w for _ in range(h)]
    comps = []
    for r in range(h):
        for c in range(w):
            if seen[r][c]:
                continue
            color = grid[r][c]
            q = deque([(r, c)])
            seen[r][c] = True
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and not seen[ny][nx] and grid[ny][nx] == color:
                        seen[ny][nx] = True
                        q.append((ny, nx))
            comps.append((color, cells))

    # Remove singleton-only colors; an isolated singleton can also be a
    # legitimate color if it is the sole connected component of the pattern,
    # but these tasks use them as marks over multicolor objects.
    multi = {color for color, cells in comps if len(cells) > 1}
    noise = {color for color, _ in comps} - multi
    totals = Counter(v for row in grid for v in row)
    background = totals.most_common(1)[0][0]
    noise.discard(background)

    out = [row[:] for row in grid]
    for color, cells in comps:
        if color not in noise:
            continue
        for r, c in cells:
            # Local non-noise mode, using the full 8-neighborhood.
            freq = Counter(grid[y][x]
                           for y in range(max(0, r - 1), min(h, r + 2))
                           for x in range(max(0, c - 1), min(w, c + 2))
                           if (y, x) != (r, c) and grid[y][x] not in noise)
            if not freq:
                out[r][c] = background
                continue
            top = max(freq.values())
            choices = {v for v, n in freq.items() if n == top}
            # Straight-through continuity wins for cells interrupting a row/column.
            if r > 0 and r + 1 < h and grid[r - 1][c] == grid[r + 1][c] and grid[r - 1][c] in choices:
                out[r][c] = grid[r - 1][c]
            elif c > 0 and c + 1 < w and grid[r][c - 1] == grid[r][c + 1] and grid[r][c - 1] in choices:
                out[r][c] = grid[r][c - 1]
            elif color in choices:
                out[r][c] = color
            elif len(choices) == 1:
                out[r][c] = next(iter(choices))
            else:
                out[r][c] = background if background in choices else min(choices)
    return out
