def transform(grid):
    h, w = len(grid), len(grid[0])
    totals = Counter(v for row in grid for v in row)
    background = totals.most_common(1)[0][0]

    seen = [[False] * w for _ in range(h)]
    components = []
    for r in range(h):
        for c in range(w):
            if seen[r][c]:
                continue
            color = grid[r][c]
            q = deque([(r, c)])
            seen[r][c] = True
            cells = []
            min_r = max_r = r
            min_c = max_c = c
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                min_r, max_r = min(min_r, y), max(max_r, y)
                min_c, max_c = min(min_c, x), max(max_c, x)
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and not seen[ny][nx]
                            and grid[ny][nx] == color):
                        seen[ny][nx] = True
                        q.append((ny, nx))
            components.append((color, cells, min_r, max_r, min_c, max_c))

    multi_colors = {color for color, cells, *_ in components if len(cells) > 1}
    all_colors = set(totals)
    noise_colors = all_colors - multi_colors
    output = [row[:] for row in grid]

    # For every singleton-color speck, restore a missing cell in a nearly
    # rectangular non-background component when its bounding box contains it.
    for r in range(h):
        for c in range(w):
            if grid[r][c] not in noise_colors:
                continue
            candidates = []
            for color, cells, r0, r1, c0, c1 in components:
                if color == background or color in noise_colors or not (r0 <= r <= r1 and c0 <= c <= c1):
                    continue
                area = (r1 - r0 + 1) * (c1 - c0 + 1)
                if area <= 1:
                    continue
                # Treat this speck as the missing pixel for rectangle density.
                completeness = (len(cells) + 1) / area
                if completeness < 0.72:
                    continue
                adjacent = sum(1 for y, x in ((r-1,c),(r+1,c),(r,c-1),(r,c+1))
                               if 0 <= y < h and 0 <= x < w and grid[y][x] == color)
                candidates.append((completeness, adjacent, len(cells), color))
            if candidates:
                candidates.sort(reverse=True)
                output[r][c] = candidates[0][3]
            else:
                output[r][c] = background
    return output
