                cells.append((y, x))
                r0, r1 = min(r0, y), max(r1, y)
                c0, c1 = min(c0, x), max(c1, x)
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and not seen[ny][nx]
                            and grid[ny][nx] == color):
                        seen[ny][nx] = True
                        q.append((ny, nx))
            components.append((color, cells, r0, r1, c0, c1))

    # Any color made only of isolated single cells is a set of speckle marks.
    colors = {v for row in grid for v in row}
