 "content": "from collections import Counter, deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    # Main canvas is the most common color (all demos use an overwhelmingly
    # dominant background). All singleton components of other colors are marks.
    totals = Counter(v for row in grid for v in row)
    background = totals.most_common(1)[0][0]
    seen = [[False] * w for _ in range(h)]
    components = []
    for r in range(h):
        for c in range(w):
            if seen[r][c]:
                continue
            color = grid[r][c]
            q = deque([(r, c)])
            seen[r][c] = True
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and not seen[ny][nx] and grid[ny][nx] == color:
                        seen[ny][nx] = True
                        q.append((ny, nx))
            components.append((color, cells))

    noise = {color for color, cells in components if len(cells) == 1 and color != background}
    out = [row[:] for row in grid]
    # Remove all isolated marks. Where a mark is embedded in a substantial
    # object, restore the majority local color; otherwise it becomes background.
    for r in range(h):
        for c in range(w):
            if grid[r][c] not in noise:
                continue
            neighborhood = [grid[y][x]
                            for y in range(max(0, r-1), min(h, r+2))
                            for x in range(max(0, c-1), min(w, c+2))
                            if (y, x) != (r, c) and grid[y][x] not in noise]
            if not neighborhood:
                out[r][c] = background
                continue
            freq = Counter(neighborhood)
            best = max(freq.values())
            choices = [v for v,n in freq.items() if n == best]
            if len(choices) == 1:
                out[r][c] = choices[0]
            elif background in choices:
                out[r][c] = background
            else:
                out[r][c] = choices[0]
    return out
